    name: "appserviceplan",
    location: exampleResourceGroup.location,
    resourceGroupName: exampleResourceGroup.name,
    sku: {
        tier: "Premium",
        size: "P1",
    },
});
const exampleAppService = new azure.appservice.AppService("example", {
