> **Note:** File upload can be defined either directly on the <span pulumi-lang-nodejs="`azure.iot.IoTHub`" pulumi-lang-dotnet="`azure.iot.IoTHub`" pulumi-lang-go="`iot.IoTHub`" pulumi-lang-python="`iot.IoTHub`" pulumi-lang-yaml="`azure.iot.IoTHub`" pulumi-lang-java="`azure.iot.IoTHub`" pulumi-lang-hcl="`azurerm_iothub`">`azure.iot.IoTHub`</span> resource, or using the <span pulumi-lang-nodejs="`azure.iot.FileUpload`" pulumi-lang-dotnet="`azure.iot.FileUpload`" pulumi-lang-go="`iot.FileUpload`" pulumi-lang-python="`iot.FileUpload`" pulumi-lang-yaml="`azure.iot.FileUpload`" pulumi-lang-java="`azure.iot.FileUpload`" pulumi-lang-hcl="`azurerm_iothub_file_upload`">`azure.iot.FileUpload`</span> resource - but the two cannot be used together. If both are used against the same IoTHub, spurious changes will occur.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as azure from "@pulumi/azure";

const example = new azure.core.ResourceGroup("example", {
    name: "example-resources",
    location: "West Europe",
});
const exampleAccount = new azure.storage.Account("example", {
    name: "examplestorage",
    resourceGroupName: example.name,
    location: example.location,
    accountTier: "Standard",
    accountReplicationType: "LRS",
});
const exampleContainer = new azure.storage.Container("example", {
    name: "examplecontainer",
    storageAccountName: exampleAccount.name,
    containerAccessType: "private",
});
const exampleIoTHub = new azure.iot.IoTHub("example", {
    name: "example",
    resourceGroupName: example.name,
    location: example.location,
    sku: {
        name: "S1",
        capacity: 1,
    },
});
const exampleFileUpload = new azure.iot.FileUpload("example", {
    iothubId: exampleIoTHub.id,
    connectionString: exampleAccount.primaryBlobConnectionString,
    containerName: exampleContainer.name,
});
