                    .permissions("r")
                    .build())
                .build())
            .build());

        var exampleSyncCloudEndpoint = new SyncCloudEndpoint("exampleSyncCloudEndpoint", SyncCloudEndpointArgs.builder()
            .name("example-ss-ce")
