					PrivateIpAddress:           pulumi.String("10.0.2.5"),
					PublicIpAddressId:          examplePublicIp.ID(),
				},
			},
		})
		if err != nil {
			return err
		}
		exampleVirtualMachine, err := compute.NewVirtualMachine(ctx, "example", &compute.VirtualMachineArgs{
